<?php
namespace App\Services;
use App\Models\NewsArticle;use App\Models\User;use Illuminate\Validation\ValidationException;
class NewsEditorialWorkflowService{
 public const ACTIONS=['submit_review'=>'journalist_review','submit_verification'=>'verification','submit_editorial'=>'editorial_review','approve'=>'approved','reject'=>'rejected','request_changes'=>'changes_requested','schedule'=>'scheduled','publish'=>'published'];
 public function snapshot(NewsArticle $a,?User $u):void{$last=(int)$a->versions()->max('version');$a->versions()->create(['created_by'=>$u?->id,'version'=>$last+1,'title'=>$a->title,'subtitle'=>$a->subtitle,'excerpt'=>$a->excerpt,'body'=>$a->body,'metadata'=>['workflow_status'=>$a->workflow_status,'ai_execution_id'=>$a->ai_execution_id]]);}
 public function transition(NewsArticle $a,User $u,string $action,?string $note,?string $scheduledFor):void{$to=self::ACTIONS[$action]??throw ValidationException::withMessages(['action'=>'Ação inválida.']);$from=$a->workflow_status?:'draft';if(in_array($action,['approve','schedule','publish'],true)&&!$u->hasAnyRole(['Super Admin','Admin']))abort(403);if($action==='publish'&&!in_array($from,['approved','scheduled'],true))throw ValidationException::withMessages(['action'=>'Aprovação humana obrigatória antes da publicação.']);if($action==='schedule'&&blank($scheduledFor))throw ValidationException::withMessages(['scheduled_for'=>'Informe a data do agendamento.']);$data=['workflow_status'=>$to];if($action==='approve')$data+=['approved_by'=>$u->id,'approved_at'=>now()];if($action==='schedule')$data['scheduled_for']=$scheduledFor;if($action==='publish')$data+=['status'=>'published','published_by'=>$u->id,'published_at'=>now()];else $data['status']='draft';$a->update($data);$a->editorialReviews()->create(['user_id'=>$u->id,'action'=>$action,'from_status'=>$from,'to_status'=>$to,'note'=>$note]);}
}
